// Stream source utilities - organized, comprehensive, and maintainable

// Types
export interface StreamLink {
  name: string;
  url: string;
  quality: string;
  server: string;
  isDefault?: boolean;
  embed?: boolean;
  /** Priority for sorting (lower = higher priority) */
  priority?: number;
  /** Whether this server is known to be reliable */
  reliability?: 'high' | 'medium' | 'low';
}

export interface StreamValidationResult {
  url: string;
  server: string;
  status: 'valid' | 'invalid' | 'unknown' | 'blocked';
  responseTime?: number;
  error?: string;
}

