// Quality presets
const QUALITY_PRESETS: Record<string, string> = {
  default: '1080p',
  high: '4K',
  standard: '1080p',
  low: '720p',
  mobile: '480p',
};

// Generate hash from string (replacement for crypto.randomUUID)
function generateHash(str: string): string {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash; // Convert to 32-bit integer
  }
  return Math.abs(hash).toString(36);
}

// Pre-compute memoized hash
const hashCache = new Map<string, string>();

function memoizedHash(str: string): string {
  if (hashCache.has(str)) return hashCache.get(str)!;
  const result = generateHash(str);
  hashCache.set(str, result);
  return result;
}

// LRU cache for stream validation results
const validationCache = new Map<string, { result: StreamValidationResult; timestamp: number }>();
const VALIDATION_TTL = 1000 * 60 * 30; // 30 minutes
const MAX_VALIDATION_CACHE = 50;

function evictValidationCache(): void {
  if (validationCache.size > MAX_VALIDATION_CACHE) {
    const firstKey = validationCache.keys().next().value;
    if (firstKey) validationCache.delete(firstKey);
  }
}

