// Generate direct stream links
export function generateDirectStreamLinks(
  imdbId: string,
  _mediaId: number,
  type: 'movie' | 'tv',
  season?: number,
  episode?: number
): StreamLink[] {
  const links: StreamLink[] = [];

  if (type === 'movie') {
    links.push({
      name: 'Direct MP4',
      url: `https://www.mp4video.dev/2/${imdbId}`,
      quality: QUALITY_PRESETS.standard,
      server: 'mp4video',
      priority: 10,
      reliability: 'low',
    });
  } else if (season && episode) {
    const seasonEpisodeStr = `${imdbId}-${season}-${episode}`;
    links.push({
      name: 'Direct MP4',
      url: `https://www.mp4video.dev/2/${seasonEpisodeStr}`,
      quality: QUALITY_PRESETS.standard,
      server: 'mp4video',
      priority: 10,
      reliability: 'low',
    });
  }

  return links;
}

// Get all stream links for an item
export function getStreamLinksForItem(
  imdbId: string,
  mediaId: number,
  type: 'movie' | 'tv',
  season?: number,
  episode?: number
): StreamLink[] {
  let links: StreamLink[];

  if (type === 'movie') {
    links = [
      ...generateMovieEmbedSources(imdbId, mediaId),
      ...generateDirectStreamLinks(imdbId, mediaId, 'movie'),
    ];
  } else {
    links = [
      ...generateTVEmbedSources(imdbId, mediaId, season || 1, episode || 1),
      ...generateDirectStreamLinks(imdbId, mediaId, 'tv', season, episode),
    ];
  }

  // Sort by priority (lower number = higher priority)
  return links.sort((a, b) => (a.priority ?? 99) - (b.priority ?? 99));
}

// Validate a stream URL (non-blocking, cached)
export async function validateStreamUrl(url: string, server: string): Promise<StreamValidationResult> {
  const cacheKey = `${server}:${url}`;
  const cached = validationCache.get(cacheKey);

  if (cached && Date.now() - cached.timestamp < VALIDATION_TTL) {
    return cached.result;
  }

  try {
    const startTime = Date.now();
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 5000);

    const response = await fetch(url, {
      method: 'HEAD',
      mode: 'no-cors',
      signal: controller.signal,
    });

    clearTimeout(timeout);
    const responseTime = Date.now() - startTime;

    const result: StreamValidationResult = {
      url,
      server,
      status: 'valid',
      responseTime,
    };

    evictValidationCache();
    validationCache.set(cacheKey, { result, timestamp: Date.now() });

    return result;
  } catch {
    const result: StreamValidationResult = {
      url,
      server,
      status: 'unknown',
      error: 'Validation timeout or blocked (expected for embeds)',
    };

    evictValidationCache();
    validationCache.set(cacheKey, { result, timestamp: Date.now() });

    return result;
  }
}

// Get quality label
export function getStreamQuality(quality: string): string {
  return quality || '1080p';
}

// Get server name
export function getStreamServerName(server: string): string {
  return SERVER_CONFIG[server]?.name || server;
}

// Get default source name
export function getDefaultSourceName(sourceKey: string): string {
  return SERVER_CONFIG[sourceKey]?.name || sourceKey;
}

// Validate stream URL format
export function isValidStreamUrl(url: string): boolean {
  try {
    new URL(url);
    return url.startsWith('http://') || url.startsWith('https://');
  } catch {
    return false;
  }
}

// Get all available servers
export function getAvailableServers(): { key: string; name: string; reliability: 'high' | 'medium' | 'low' }[] {
  return Object.entries(SERVER_CONFIG).map(([key, config]) => ({
    key,
    name: config.name,
    reliability: config.reliability,
  }));
}

// Get servers filtered by reliability
export function getServersByReliability(reliability: 'high' | 'medium' | 'low'): { key: string; name: string }[] {
  return Object.entries(SERVER_CONFIG)
    .filter(([, config]) => config.reliability === reliability)
    .map(([key, config]) => ({ key, name: config.name }));
}

// Get all available qualities
export const AVAILABLE_QUALITIES = ['4K', '1080p', '720p', '480p'];

// Get all available servers for filtering
export const AVAILABLE_SERVERS = Object.values(SERVER_CONFIG).map(
  config => config.name
);

// Get high-reliability servers (recommended)
export const RECOMMENDED_SERVERS = getServersByReliability('high').map(({ key, name }) => ({ key, name }));

